<script setup lang="ts">
import {ref,onMounted,computed,watch} from 'vue'
import {api,ApiError,type Account} from './api'
const props=defineProps<{account:Account}>(),emit=defineEmits<{expired:[]}>()
type Row=Record<string,any>
const importStates: Record<string, string> = { PENDING: '待处理', SUCCESS: '成功', FAILED: '失败', DUPLICATE: '重复，未新增' }
const analyst=computed(()=>props.account.roles.includes('CENTER_ANALYST')),admin=computed(()=>props.account.roles.includes('CENTER_ADMIN'))
const error=ref(''),message=ref(''),busy=ref(false),sources=ref<Row[]>([]),source=ref<number>(),mappingId=ref<number>(),mappings=ref<Row[]>([]),batches=ref<Row[]>([]),rows=ref<Row[]>([]),selected=ref<number>(),file=ref<File>(),credentials=ref<Row[]>([]),token=ref(''),receipts=ref<Row[]>([])
const personId=ref<number>(),detail=ref<Row>(),reason=ref(''),manual=ref('MEDIUM'),ruleData=ref<Row>(),draft=ref<Row>(),preview=ref<Row>()
const thresholds=ref({medium:3,high:5}),keywords=ref<Row[]>([])
const fields=['personName','idCard','phone','eventTime','description','categoryId','disputeId'],labels=['姓名','身份证号','手机号','发生时间','问题描述','事件分类','纠纷类型']
const mappingName=ref(''),columns=ref<Record<string,string>>(Object.fromEntries(fields.map((f,i)=>[f,labels[i]]))),categoryAliases=ref(''),disputeAliases=ref(''),timeFormat=ref('ISO')
const credential=ref({name:'',departmentId:0,sourceId:0,specialReport:false})
const availableMappings=computed(()=>mappings.value.filter(m=>m.source_id===source.value))
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';message.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:'操作失败';if(e instanceof ApiError&&e.status===401)emit('expired')}finally{busy.value=false}}
const post=<T,>(path:string,data:unknown)=>api<T>(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)})
async function refresh(){sources.value=await api('/options/sources');if(analyst.value||props.account.roles.includes('DEPARTMENT_REPORTER')){mappings.value=await api('/batches/mappings');batches.value=await api('/batches')}if(analyst.value){ruleData.value=await api('/risk-governance/rules');receipts.value=await api('/batches/receipts')}if(admin.value)credentials.value=await api('/batches/credentials')}
async function openPerson(){detail.value=await api('/risk-governance/people/'+personId.value)}
async function adjust(){await post('/risk-governance/adjustments',{personId:personId.value,level:manual.value,fingerprint:detail.value!.fingerprint,reason:reason.value});await openPerson();message.value='人工调整已保存'}
async function exclude(item:Row){await post('/risk-governance/exclusions',{personId:personId.value,eventId:item.hit.eventId,ruleId:item.hit.ruleId,fingerprint:item.fingerprint,reason:reason.value});await openPerson();message.value='误命中已排除，风险已更新'}
function newDraft(){const active=ruleData.value!.active;thresholds.value={medium:active.medium,high:active.high};keywords.value=active.keywords.map((k:Row)=>({...k,terms:[...k.terms]}));draft.value=undefined;preview.value=undefined}
function editDraft(row:Row){const value=typeof row.payload==='string'?JSON.parse(row.payload):row.payload;thresholds.value={medium:value.medium,high:value.high};keywords.value=value.keywords;draft.value=row;preview.value=undefined}
watch([thresholds,keywords],()=>{preview.value=undefined},{deep:true})
async function saveDraft(){draft.value=await post('/risk-governance/rules',{id:draft.value?.id,version:draft.value?.version,rules:{...thresholds.value,keywords:keywords.value}});preview.value=undefined;await refresh();message.value='规则草稿已保存'}
async function doPreview(){preview.value=await post('/risk-governance/rules/'+draft.value!.id+'/preview',{})}
async function publish(){await post('/risk-governance/rules/'+draft.value!.id+'/publish',{version:draft.value!.version});draft.value=undefined;preview.value=undefined;await refresh();message.value='规则已发布，请刷新查看重算进度'}
async function upload(){if(!file.value||!source.value)throw Error('请选择来源和文件');const form=new FormData();form.append('file',file.value);form.append('sourceId',String(source.value));if(mappingId.value)form.append('mappingId',String(mappingId.value));const result=await api<Row>('/batches',{method:'POST',body:form});selected.value=result.id;await refresh();rows.value=await api('/batches/'+result.id);message.value='已接收，请刷新查看逐行结果'}
function aliases(value:string){return Object.fromEntries(value.split('\n').filter(Boolean).map(line=>{const i=line.indexOf('=');if(i<1)throw Error('别名格式为 原值=标准分类编号，每行一条');return [line.slice(0,i),line.slice(i+1)]}))}
async function saveMapping(){await post('/batches/mappings',{name:mappingName.value,sourceId:source.value,columns:columns.value,categories:aliases(categoryAliases.value),disputes:aliases(disputeAliases.value),timeFormat:timeFormat.value});await refresh();message.value='映射版本已保存'}
onMounted(()=>run(refresh))
</script>
<template><main class="content governance-workspace"><div class="page-heading"><div><p class="eyebrow">规则治理与数据接入</p><h1>规则与批量接入</h1><p class="muted">管理风险规则与接入配置，跟踪批量处理结果。</p></div><el-button :disabled="busy" @click="run(refresh)">刷新进度</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-alert v-if="message" :title="message" type="success" :closable="false"/><el-tabs>
<el-tab-pane v-if="analyst||account.roles.includes('DEPARTMENT_REPORTER')" label="批量导入"><section class="event-card"><h2>批量文件导入</h2><el-form class="import-form" label-position="top"><div class="form-grid"><el-form-item label="可信数据来源"><el-select v-model="source" @change="mappingId=undefined"><el-option v-for="s in sources" :key="s.id" :label="s.name" :value="s.id"/></el-select></el-form-item><el-form-item label="来源映射版本"><el-select v-model="mappingId" clearable placeholder="统一模板"><el-option v-for="m in availableMappings" :key="m.id" :value="m.id" :label="m.name+' · 版本 '+m.version"/></el-select></el-form-item></div><p v-if="source" class="template-links"><a :href="`/api/batches/template?sourceId=${source}&format=csv${mappingId?'&mappingId='+mappingId:''}`">下载 CSV 模板</a> · <a :href="`/api/batches/template?sourceId=${source}&format=xlsx${mappingId?'&mappingId='+mappingId:''}`">下载 Excel 模板</a></p><div class="upload-row"><input type="file" accept=".csv,.xlsx" aria-label="导入文件" @change="file=($event.target as HTMLInputElement).files?.[0]"/><el-button type="primary" :disabled="busy" @click="run(upload)">提交批量导入</el-button></div></el-form><p class="help-note">最多10000行、5MB。事件分类和纠纷类型直接填写“来源与分类”中已启用的名称，无需填写编号。错误行不影响其他行；下载失败行修正后重导。身份证和日期请使用文本单元格，日期格式默认为 ISO，例如 2026-10-18T12:00:00。</p><h3 class="section-heading">导入批次</h3><el-table :data="batches"><el-table-column prop="id" label="批次"/><el-table-column prop="filename" label="文件" min-width="150" show-overflow-tooltip/><el-table-column prop="total" label="总行数"/><el-table-column prop="pending" label="待处理"/><el-table-column prop="succeeded" label="成功"/><el-table-column prop="duplicates" label="重复"/><el-table-column prop="failed" label="失败"/><el-table-column label="操作" width="230"><template #default="{row}"><div class="table-actions"><el-button link type="primary" @click="run(async()=>{selected=row.id;rows=await api('/batches/'+row.id)})">逐行结果</el-button><a :href="`/api/batches/${row.id}/failures`">失败文件</a> · <a :href="`/api/batches/${row.id}/original`">原文件</a></div></template></el-table-column></el-table><section v-if="selected" class="detail-panel"><h3>批次 #{{selected}} · 逐行结果</h3><el-table :data="rows"><el-table-column prop="line_number" label="原始行号"/><el-table-column label="结果" min-width="130"><template #default="{row}"><el-tag :type="row.state==='SUCCESS'?'success':row.state==='FAILED'?'danger':row.state==='PENDING'?'warning':'info'" effect="plain">{{ importStates[row.state] || '未知状态' }}</el-tag></template></el-table-column><el-table-column prop="record_id" label="来源记录"/><el-table-column prop="error" label="失败原因" min-width="200"/></el-table></section></section></el-tab-pane>
<el-tab-pane v-if="analyst" label="误命中与人工调整"><section class="event-card"><h2>误命中与人工调整</h2><div class="tools-toolbar"><el-input-number v-model="personId" :min="1" aria-label="风险人员编号"/><el-button :disabled="busy" @click="run(openPerson)">查看调整依据</el-button></div><section v-if="detail" class="detail-panel"><p>规则等级：{{detail.snapshot.ruleLevel}} · 有效人工调整：{{detail.snapshot.manualLevel||'无或已失效'}} · 最终等级：{{detail.snapshot.finalLevel}}</p><el-form label-position="top" class="adjustment-form"><el-form-item label="排除或调整理由"><el-input v-model="reason" placeholder="排除或调整理由（必填）" aria-label="风险调整理由" type="textarea" :rows="3"/></el-form-item><el-form-item label="人工调整等级"><el-select v-model="manual"><el-option v-for="l in ['LOW','MEDIUM','HIGH']" :key="l" :value="l" :label="l"/></el-select></el-form-item><el-button type="primary" :disabled="busy" @click="run(adjust)">保存人工调整</el-button></el-form><article v-for="item in detail.hits" :key="item.hit.eventId+'-'+item.hit.ruleId"><h3>事件 #{{item.hit.eventId}} · {{item.hit.ruleName}}</h3><p v-for="e in item.hit.evidence" :key="e.recordId+'-'+e.field+'-'+e.term">来源 #{{e.recordId}} · {{e.field}}：{{e.text}}</p><el-button :disabled="busy" @click="run(()=>exclude(item))">排除此误命中</el-button></article><h3>调整历史（依据变化后自动失效）</h3><el-table :data="detail.adjustments"><el-table-column label="依据状态"><template #default="{row}">{{row.active?'依据未失效':'已失效'}}</template></el-table-column><el-table-column prop="level" label="调整等级"/><el-table-column prop="reason" label="原因"/><el-table-column prop="actor" label="操作者"/><el-table-column prop="created_at" label="时间"/></el-table><h3>计算历史</h3><el-table :data="detail.history"><el-table-column prop="created_at" label="计算时间"/><el-table-column label="历史依据"><template #default="{row}"><details><summary>查看历史规则和证据</summary><pre>{{JSON.stringify(typeof row.snapshot==='string'?JSON.parse(row.snapshot):row.snapshot,null,2)}}</pre></details></template></el-table-column></el-table><h3>排除历史</h3><el-table :data="detail.exclusions"><el-table-column label="状态"><template #default="{row}">{{row.active?'有效':'已失效'}}</template></el-table-column><el-table-column prop="event_id" label="事件"/><el-table-column prop="rule_id" label="规则"/><el-table-column prop="reason" label="原因"/></el-table></section></section></el-tab-pane>
<el-tab-pane v-if="analyst" label="规则发布"><section class="event-card"><h2>规则草稿与发布</h2><p class="help-note">特殊来源中风险保底固定生效。组合词在同一有效事件内同时出现才命中。</p><el-button :disabled="busy" @click="newDraft">新建规则草稿</el-button><el-form class="rule-form" label-position="top"><el-form-item label="中风险起始次数"><el-input-number v-model="thresholds.medium" :min="1"/></el-form-item><el-form-item label="高风险起始次数"><el-input-number v-model="thresholds.high" :min="2"/></el-form-item><div v-for="k in keywords" :key="k.id" class="keyword-row"><el-input v-model="k.name" placeholder="规则名称" aria-label="规则名称"/><el-input :model-value="k.terms.join('、')" placeholder="组合关键词用顿号隔开" @update:model-value="k.terms=$event.split('、')"/><el-switch v-model="k.enabled" active-text="启用"/></div><el-button @click="keywords.push({id:Math.max(0,...keywords.map(k=>k.id))+1,name:'',terms:[''],enabled:true,version:1})">增加关键词规则</el-button><el-button :disabled="busy" @click="run(saveDraft)">保存规则草稿</el-button><el-button :disabled="busy||!draft" @click="run(doPreview)">预览影响</el-button><p v-if="preview">受影响 {{preview.affected}} 人 · 升级 {{preview.up}} 人 · 降级 {{preview.down}} 人</p><el-button :disabled="busy||!preview" @click="run(publish)">发布规则</el-button></el-form><h3 class="section-heading">规则版本</h3><el-table :data="ruleData?.releases"><el-table-column prop="id" label="规则版本"/><el-table-column prop="state" label="状态"/><el-table-column label="操作"><template #default="{row}"><el-button v-if="row.state==='DRAFT'" link @click="editDraft(row)">编辑草稿</el-button><el-button link @click="editDraft({...row,id:undefined,version:undefined})">复制配置</el-button></template></el-table-column></el-table><h3 class="section-heading">后台重算进度</h3><el-table :data="ruleData?.jobs"><el-table-column prop="id" label="重算任务"/><el-table-column prop="state" label="状态"/><el-table-column prop="completed" label="已完成"/><el-table-column prop="total" label="总人数"/><el-table-column prop="error" label="失败原因"/><el-table-column label="操作"><template #default="{row}"><el-button v-if="row.state==='FAILED'" link @click="run(async()=>{await post('/risk-governance/jobs/'+row.id+'/retry',{});await refresh()})">重试</el-button></template></el-table-column></el-table></section></el-tab-pane>
<el-tab-pane v-if="analyst" label="来源映射"><section class="event-card"><h2>来源字段映射</h2><p class="help-note">先在批量导入页选择来源。保存同名映射会新增版本，旧批次保留原映射。</p><el-form class="mapping-form" label-position="top"><el-form-item label="映射名称"><el-input v-model="mappingName" placeholder="映射名称"/></el-form-item><el-form-item v-for="(f,i) in fields" :key="f" :label="labels[i]+'对应列名'"><el-input v-model="columns[f]"/></el-form-item><el-form-item label="日期转换"><el-select v-model="timeFormat"><el-option v-for="f in ['ISO','yyyy/MM/dd HH:mm:ss','yyyy-MM-dd HH:mm:ss']" :key="f" :value="f"/></el-select></el-form-item><el-form-item label="事件分类别名"><el-input v-model="categoryAliases" type="textarea" :rows="3" placeholder="事件分类别名：原值=标准分类编号，每行一条"/></el-form-item><el-form-item label="纠纷类型别名"><el-input v-model="disputeAliases" type="textarea" :rows="3" placeholder="纠纷类型别名：原值=标准分类编号，每行一条"/></el-form-item><el-button :disabled="busy" @click="run(saveMapping)">保存映射新版本</el-button></el-form></section></el-tab-pane>
<el-tab-pane v-if="admin" label="外部接入凭据"><section class="event-card"><h2>外部接入凭据</h2><el-form class="credential-form" label-position="top"><el-form-item label="凭据名称"><el-input v-model="credential.name"/></el-form-item><el-form-item label="绑定部门编号"><el-input-number v-model="credential.departmentId" :min="1"/></el-form-item><el-form-item label="绑定来源"><el-select v-model="credential.sourceId"><el-option v-for="s in sources" :key="s.id" :label="s.name" :value="s.id"/></el-select></el-form-item><el-form-item label="上报权限"><el-switch v-model="credential.specialReport" active-text="允许特殊上报"/></el-form-item><el-button :disabled="busy" @click="run(async()=>{const c=await post<Row>('/batches/credentials',credential);token=c.token;await refresh()})">创建凭据</el-button></el-form><p v-if="token">仅本次显示，请保存：<code>{{token}}</code></p><el-table :data="credentials"><el-table-column prop="name" label="名称"/><el-table-column prop="department_id" label="部门"/><el-table-column prop="source_id" label="来源"/><el-table-column prop="enabled" label="启用"/><el-table-column label="操作"><template #default="{row}"><el-button :disabled="busy||!row.enabled" @click="run(async()=>{await api('/batches/credentials/'+row.id,{method:'DELETE'});await refresh()})">停用凭据</el-button></template></el-table-column></el-table></section></el-tab-pane>
<el-tab-pane v-if="analyst" label="外部接收结果"><section class="event-card"><h2>外部接收结果</h2><el-table :data="receipts"><el-table-column prop="name" label="凭据"/><el-table-column prop="external_id" label="外部编号"/><el-table-column prop="record_id" label="来源记录"/><el-table-column prop="error" label="失败原因"/><el-table-column prop="created_at" label="接收时间"/></el-table></section></el-tab-pane>
</el-tabs></main></template>

<style scoped>
.governance-workspace :deep(.el-tabs__header) { margin-bottom: 16px; }
.event-card { padding: 24px; }
.event-card h2 { font-size: 18px; font-weight: 600; margin-bottom: 24px; }
.event-card h3 { font-size: 16px; }
.form-grid, .mapping-form { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); column-gap: 24px; }
.mapping-form > .el-button { grid-column: 1 / -1; justify-self: start; }
.upload-row { display: flex; flex-wrap: wrap; align-items: center; gap: 16px; padding: 16px; border: 1px dashed #cddbd6; border-radius: 6px; background: #f7faf9; }
.upload-row input { max-width: 100%; min-width: 0; flex: 1 1 260px; font-size: 13px; color: #657585; }
.upload-row input::file-selector-button { padding: 8px 14px; margin-right: 12px; border: 1px solid #d9e3df; border-radius: 4px; background: #fff; color: #246c64; cursor: pointer; }
.help-note { color: #657585; font-size: 13px; line-height: 1.9; margin: 16px 0 24px; }
.governance-workspace a { color: #246c64; text-decoration: none; }
.governance-workspace a:hover { text-decoration: underline; }
.template-links { font-size: 13px; }
.table-actions { display: flex; align-items: center; flex-wrap: wrap; gap: 8px; }
.table-actions a { white-space: nowrap; }
.section-heading, .detail-panel { border-top: 1px solid #edf0f4; padding-top: 24px; margin-top: 24px; }
.tools-toolbar { display: flex; align-items: center; flex-wrap: wrap; gap: 12px; }
.adjustment-form, .credential-form { max-width: 620px; margin-bottom: 24px; }
.rule-form { margin-top: 24px; }
.keyword-row { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 2fr) auto; align-items: center; gap: 12px; padding: 16px; margin-bottom: 16px; background: #f6f8fa; border-radius: 6px; }
.rule-form > .el-button { margin: 0 10px 10px 0; }
.detail-panel article { margin: 24px 0; padding: 20px; background: #f6f8fa; border-radius: 6px; }
.event-card pre, .event-card code { white-space: pre-wrap; overflow-wrap: anywhere; }
.detail-panel p { line-height: 1.8; overflow-wrap: anywhere; }
@media (max-width: 850px) {
  .form-grid, .mapping-form { grid-template-columns: minmax(0, 1fr); }
  .keyword-row { grid-template-columns: minmax(0, 1fr); }
}
@media (max-width: 600px) {
  .event-card { padding: 16px; }
  .page-heading { flex-wrap: wrap; gap: 12px; }
}
</style>
